curl -s -X POST "https://slack.com/api/users.list" \
  -H "Authorization: Bearer <TOKEN>" \
  -d "team_id=T0001" | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data.get('ok'):
    for u in data['members']:
        if u.get('is_owner'):
            print(f'Owner: {u[\"id\"]} - {u.get(\"profile\",{}).get(\"real_name\",\"?\")}')
else:
    print('Error:', data)
"

curl -s -X POST "https://slack.com/api/users.conversations" \
  -H "Authorization: Bearer <TOKEN>" \
  -d "user=U_NINA&limit=100&exclude_archived=true" | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data.get('ok'):
    for c in data['channels']:
        print(f'{c[\"id\"]} | {c[\"name\"]} | is_private={c[\"is_private\"]} | created={c[\"created\"]}')
    if data.get('response_metadata', {}).get('next_cursor'):
        print(f'NEXT_CURSOR: {data[\"response_metadata\"][\"next_cursor\"]}')
else:
    print('Error:', data)
"
